fichiersCorriges.requetes.sql:
-- Q1
SELECT titre, auteur FROM Livre WHERE categorie = 'Roman' ORDER BY titre;
-- Q2
SELECT nom, prenom FROM Eleve WHERE classe = '4SI1' AND YEAR(dateNaiss) = 2008;
-- Q3
SELECT titre FROM Livre, Emprunt WHERE Livre.codeLivre = Emprunt.codeLivre AND numEl = 3;
-- Q4
SELECT titre, annee FROM Livre WHERE annee BETWEEN 2000 AND 2010;
-- Q5
SELECT nom, prenom FROM Eleve WHERE nom LIKE 'B%';
-- Q6
SELECT categorie, COUNT(*) AS nbEmprunts FROM Livre, Emprunt WHERE Livre.codeLivre = Emprunt.codeLivre GROUP BY categorie;
-- Q7
SELECT categorie, COUNT(*) AS nbEmprunts FROM Livre, Emprunt WHERE Livre.codeLivre = Emprunt.codeLivre GROUP BY categorie HAVING COUNT(*) > 4;
-- Q8
SELECT codeLivre, dateEmprunt FROM Emprunt WHERE dateRetour IS NULL;
